<?php require __DIR__ . '/footer.php'; session_start(); $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){require __DIR__ . '/connect.php'; $email=filter_input(INPUT_POST,'email',FILTER_VALIDATE_EMAIL); $password=$_POST['password']??''; if($email){$stmt=$mysqli->prepare('SELECT id,full_name,password_hash,is_active,created_at FROM users WHERE email=?'); $stmt->bind_param('s',$email); $stmt->execute(); $user=$stmt->get_result()->fetch_assoc(); if($user&&password_verify($password,$user['password_hash'])&&(int)$user['is_active']===1){$_SESSION['user_id']=$user['id']; $_SESSION['full_name']=$user['full_name']; $_SESSION['created_at']=$user['created_at']; header('Location: dashboard.php'); exit;} $error=$user&&(int)$user['is_active']!==1?'Please activate your email before login.':'Invalid email or password.';}} ?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>C Login</title><link rel="stylesheet" href="../css/styles.css"><script defer src="../js/script.js"></script></head><body><header><h1>C.04 Login Page</h1><nav><a href="register.php">Register</a><a class="secondary" href="forgot_password.php">Forgot Password</a></nav></header><main><section class="card"><?php if($error):?><div class="notice error"><?=htmlspecialchars($error)?></div><?php endif;?><form method="post" data-validate><label>Email</label><input name="email" type="email" required><label>Password</label><input name="password" type="password" required><button>Login</button></form></section></main><?php exam_footer(); ?></body></html>
